import React from 'react'
import {
  theme,
  ButtonTransparent,
  Flex,
  FlexItem,
  Heading,
  DialogContent,
  Paragraph,
  Table,
  TableBody,
  Tabs,
  TabList,
  Tab,
  TabPanel,
  TabPanels,
} from '@looker/components'
import { LogoRings, Explore } from '@looker/icons'
import type {
  ILookmlModel,
  ILookmlModelExplore,
  ILookmlModelExploreField,
  IUser,
} from '@looker/sdk'
import { exploreFieldURL } from '../utils/urls'
import { canGetDistribution, canGetTopValues } from '../utils/queries'
import type {
  ColumnDescriptor,
  FieldComments,
  CommentPermissions,
} from './interfaces'
import { ExternalLink } from './ExternalLink'
import { QueryChart } from './QueryChart'
import { DetailDrawerRow } from './DetailDrawerRow'
import { FieldCommentList } from './FieldCommentList'

export const FieldMetadata: React.FC<{
  columns: ColumnDescriptor[]
  explore: ILookmlModelExplore
  model: ILookmlModel
  field: ILookmlModelExploreField
  tab: number
  detailsPane: (tabIndex: number) => void
  commentsPane: (tabIndex: number) => void
  sortedComments: FieldComments[]
  addComment: (newCommentStr: string, field: string) => void
  editComment: (newCommentStr: string, field: string) => void
  deleteComment: (newCommentStr: string, field: string) => void
  fieldCommentLength: number
  commentAuthors: IUser[]
  me: IUser
  permissions: CommentPermissions
  canViewComments: boolean
}> = ({
  columns,
  explore,
  field,
  model,
  tab,
  detailsPane,
  commentsPane,
  sortedComments,
  addComment,
  editComment,
  deleteComment,
  fieldCommentLength,
  commentAuthors,
  me,
  permissions,
  canViewComments,
}) => {
  return (
    <DialogContent>
      <FlexItem>
        <Heading as="h3" fontWeight="semiBold" pb="small">
          {field.label_short}
        </Heading>
        <Tabs index={tab} onChange={tab ? detailsPane : commentsPane}>
          <TabList distribute>
            <Tab>Details</Tab>
            {canViewComments ? (
              <Tab>
                Comments{fieldCommentLength > 0 && ` (${fieldCommentLength})`}
              </Tab>
            ) : (
              <></>
            )}
          </TabList>
          <TabPanels>
            <TabPanel>
              <Flex flexDirection="column">
                {field.description && (
                  <FlexItem pb="small">
                    <Paragraph>{field.description}</Paragraph>
                  </FlexItem>
                )}
                <FlexItem>
                  <Heading
                    as="h4"
                    fontSize="small"
                    fontWeight="semiBold"
                    mb="small"
                    style={{ marginTop: '2em' }}
                  >
                    About this Field
                  </Heading>
                </FlexItem>
                <FlexItem pb="medium">
                  <Table width="100%">
                    <TableBody fontSize="small">
                      {columns.map((column) => {
                        if (
                          column.rowValueDescriptor !== 'comment' &&
                          column.rowValueDescriptor !== 'description'
                        ) {
                          return (
                            <DetailDrawerRow
                              key={column.rowValueDescriptor}
                              column={column}
                              field={field}
                            />
                          )
                        }
                        return undefined
                      })}
                    </TableBody>
                  </Table>
                </FlexItem>
                <QueryChart
                  disabledText={
                    'Distributions can only be shown for numeric dimensions on a view with a count measure.'
                  }
                  enabled={canGetDistribution({ model, explore, field })}
                  type={{
                    type: 'Distribution',
                    model,
                    explore,
                    field,
                  }}
                />
                <QueryChart
                  disabledText={
                    'Values can only be shown for dimensions on a view with a count measure.'
                  }
                  enabled={canGetTopValues({ model, explore, field })}
                  type={{
                    type: 'Values',
                    model,
                    explore,
                    field,
                  }}
                />
                <FlexItem
                  borderTop={`1px solid ${theme.colors.ui3}`}
                  pt="small"
                  mb="xlarge"
                >
                  <Flex alignItems="center" justifyContent="center">
                    <ExternalLink target="_blank" href={field.lookml_link}>
                      <ButtonTransparent
                        mr="small"
                        ml="small"
                        iconBefore={<LogoRings />}
                      >
                        Go to LookML
                      </ButtonTransparent>
                    </ExternalLink>
                    <ExternalLink
                      target="_blank"
                      href={exploreFieldURL(explore, field)}
                    >
                      <ButtonTransparent
                        mr="small"
                        ml="small"
                        iconBefore={<Explore />}
                      >
                        Explore with Field
                      </ButtonTransparent>
                    </ExternalLink>
                  </Flex>
                </FlexItem>
              </Flex>
            </TabPanel>
            {canViewComments ? (
              <TabPanel>
                <FieldCommentList
                  sortedComments={sortedComments}
                  addComment={addComment}
                  editComment={editComment}
                  deleteComment={deleteComment}
                  explore={explore}
                  field={field}
                  commentAuthors={commentAuthors}
                  me={me}
                  permissions={permissions}
                />
              </TabPanel>
            ) : (
              <></>
            )}
          </TabPanels>
        </Tabs>
      </FlexItem>
    </DialogContent>
  )
}
